import {createGame,submit,available,normalize,pause,resume,tick,hint,finish,remaining,pack,restore,DICTIONARY_VERSION,DURATIONS,dictionary} from './engine.js?v=1.1.0';

const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage={get(key,fallback){try{return JSON.parse(localStorage.getItem('kek:'+key))??fallback;}catch{return fallback;}},set(key,value){try{localStorage.setItem('kek:'+key,JSON.stringify(value));return true;}catch{return false;}},remove(key){try{localStorage.removeItem('kek:'+key);}catch{}}};
const labels={calm:'Sakin akış',rush:'Zamana karşı',duel:'Düello'};
let options={mode:'calm',length:3},game=null,draft='',selected=0,typed=false,feedback='',feedbackType='',modalKind='',modalPaused=false,audio=null;
let names=storage.get('names',['Oyuncu 1','Oyuncu 2']);if(!Array.isArray(names)||names.length!==2)names=['Oyuncu 1','Oyuncu 2'];
let sound=storage.get('sound',false)===true;
let stats=storage.get('stats',{games:0,total:0,best:{},assisted:{},duels:0});
if(!stats||typeof stats!=='object'||!stats.best||!stats.assisted)stats={games:0,total:0,best:{},assisted:{},duels:0};
let saved=restore(storage.get('session',null));
const main=$('#main'),modal=$('#modal');
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function playSound(kind='success') {
  if(!sound)return;
  try {audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const t=audio.currentTime;const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='sine';o.frequency.setValueAtTime(kind==='error'?190:kind==='win'?660:480,t);o.frequency.exponentialRampToValueAtTime(kind==='error'?120:kind==='win'?990:620,t+.12);g.gain.setValueAtTime(.045,t);g.gain.exponentialRampToValueAtTime(.001,t+.23);o.start(t);o.stop(t+.24);}catch{}
}
function soundButton(){const b=$('#sound-btn');b.setAttribute('aria-pressed',String(sound));b.setAttribute('aria-label',sound?'Sesi kapat':'Sesi aç');b.innerHTML=`♪<span class="sound-state"> ${sound?'açık':'kapalı'}</span>`;}
function recordKey(){return `${game.mode}:${game.length}`;}
function persist(){if(game?.mode==='calm'&&game.status!=='ended'){const ok=storage.set('session',pack(game));if(!ok&&!game.storageWarned){game.storageWarned=true;toast('Tarayıcı kayda izin vermiyor; bu oyun yalnızca açık sekmede kalır.');}}else if(game?.mode==='calm'){storage.remove('session');saved=null;}}
function showHome(){game=null;modalKind='';if(modal.open)modal.close();saved=restore(storage.get('session',null));renderHome();}
function renderHome(){
  main.innerHTML=`<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="eyebrow"><span class="line"></span> KÜÇÜK BİR DEĞİŞİKLİKLE BAŞLAR.</div><h1 id="hero-title">Bir harf değiştir.<br><span>Oyunu değiştir.</span></h1><p>Bir kelimeden diğerine, kendi yolunu bul.<br>İster kafanı dinle, ister arkadaşına meydan oku.</p><div class="hero-chips"><span>✓ Çekim eki yok</span><span>✓ Kelime tekrarı yok</span></div></div><div class="demo-board" aria-label="Örnek: KEK, ilk harfi değiştir, ÇEK, ortadaki harfi değiştir, ÇOK"><div class="demo-top"><span>BİR KELİME, YENİ BİR YOL</span><span class="sparkle">✳</span></div><div class="demo-steps"><div class="demo-step"><span class="demo-tile">K</span><span class="demo-tile">E</span><span class="demo-tile">K</span></div><div class="demo-step"><span class="demo-arrow">↳</span><span class="demo-tile changed">Ç</span><span class="demo-tile">E</span><span class="demo-tile">K</span><span class="demo-check">✓</span></div><div class="demo-step"><span class="demo-arrow">↳</span><span class="demo-tile">Ç</span><span class="demo-tile changed peach">O</span><span class="demo-tile">K</span><span class="demo-check">✓</span></div></div><span class="demo-stamp">Sadece bir harf.<br>Gerisi sende.</span><div class="demo-caption">KEK'ten nereye gidersin? ↗</div></div></section>
  <section aria-labelledby="mode-title"><div class="section-heading"><h2 id="mode-title">Bugün nasıl oynayalım?</h2><p>Kendi ritmini seç.</p></div><div class="modes" role="group" aria-label="Oyun modu">
  ${[{id:'calm',symbol:'∞',desc:'Acele yok. Zinciri uzat,<br>kelimelerin tadını çıkar.',badge:'TEK KİŞİ · SÜRESİZ'},{id:'rush',symbol:'◷',desc:'İki dakika, açık bir zihin.<br>Kaç kelime bulabilirsin?',badge:'TEK KİŞİ · 120 SANİYE'},{id:'duel',symbol:'⇄',desc:'Sıra sende, sonra onda.<br>Rakibine zor bir yol bırak.',badge:'İKİ KİŞİ · AYNI CİHAZ'}].map(m=>`<button class="mode-card ${options.mode===m.id?'selected':''}" data-action="mode" data-mode="${m.id}" aria-pressed="${options.mode===m.id}"><span class="radio-mark" aria-hidden="true"></span><span class="mode-symbol" aria-hidden="true">${m.symbol}</span><h3>${labels[m.id]}</h3><p>${m.desc}</p><span class="mode-badge">${m.badge}</span></button>`).join('')}</div>
  ${options.mode==='duel'?`<div class="duel-names"><div class="field"><label for="player-one">Yeşil köşe</label><input id="player-one" data-player="0" maxlength="20" value="${esc(names[0])}" autocomplete="off"></div><div class="field"><label for="player-two">Şeftali köşe</label><input id="player-two" data-player="1" maxlength="20" value="${esc(names[1])}" autocomplete="off"></div></div>`:''}
  <div class="setup"><div><p class="setup-label">Kaç harfle oynayalım?</p><div class="segmented" role="group" aria-label="Kelime uzunluğu">${[3,4,5].map(n=>`<button data-action="length" data-length="${n}" class="${options.length===n?'active':''}" aria-pressed="${options.length===n}">${n} harf</button>`).join('')}</div><div class="length-help">${{3:'Kısa kelimeler, bol ihtimal.',4:'Biraz daha düşün, yeni yollar bul.',5:'Dar yollar. Daha dikkatli hamleler.'}[options.length]}</div></div><div class="start-area"><button class="primary" data-action="start">${options.mode==='duel'?'Düelloya başla':'Oyuna başla'} <span class="arrow">↗</span></button><span class="small-note">${options.mode==='duel'?'Hamle başına 30 saniye · 3 tur kazanan alır':'Üyelik yok. Hazırsan başlayalım.'}</span></div></div>
  <div class="rule-strip"><span aria-hidden="true">ⓘ</span><span>Her hamlede <strong>tek harf</strong> değişir. <strong>EVİ, EVE</strong> gibi çekimli biçimler geçmez. <button class="text-btn" data-action="rules">Tüm kurallar</button></span></div>
  ${saved?`<div class="resume-banner"><span>Yarım kalan bir yol var: <strong>${esc(saved.current)}</strong> · ${saved.moves} kelime</span><button data-action="continue">Devam et ↗</button></div>`:''}</section>`;
}
function begin(nextRound=false){
  const previous=game;
  const mode=nextRound?previous.mode:options.mode,length=nextRound?previous.length:options.length;
  game=createGame({mode,length,names,round:nextRound?previous.round+1:1,scores:nextRound?previous.scores:[0,0],starter:nextRound?1-previous.starter:0,start:!nextRound&&length===3&&stats.games===0?'KEK':undefined});
  draft=game.current;selected=0;typed=false;feedback='Bir harf seç. İlk hamlenle yol açılsın.';feedbackType='';
  closeModal(false);persist();renderGame();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});
}
function historyHTML(){return game.history.map((item,i)=>{const prev=game.history[i-1]?.word;const chars=[...item.word].map((c,j)=>prev&&!item.newChain&&prev[j]!==c?`<span class="changed-letter">${c}</span>`:c).join('');return `<li><span class="number">${String(i).padStart(2,'0')}</span><span class="word">${chars}</span>${i===0?'<small>başlangıç</small>':item.newChain?'<small>yeni yol</small>':item.player!==null?`<span class="player-dot p${item.player}" aria-label="${esc(game.names[item.player])}"></span>`:''}</li>`;}).join('');}
function playerHTML(){return `<div class="players">${game.names.map((n,i)=>`<div class="player-card p${i} ${game.turn===i?'active':''}"><span class="player-dot p${i}"></span><span class="name">${esc(n)}<span class="turn-label">${game.turn===i?'Sıra sende':'Hamleni düşün'}</span></span><span class="round-dots" aria-label="${game.scores[i]} tur kazandı">${[0,1,2].map(j=>`<i class="${j<game.scores[i]?'won':''}"></i>`).join('')}</span><span class="round-score">${game.scores[i]}</span></div>`).join('')}</div>`;}
function renderGame(){
  if(!game)return;
  main.innerHTML=`<div class="game-header"><button class="back-btn" data-action="exit">← Ana sayfa</button><span class="game-mode">${labels[game.mode]} <span class="tag">${game.length} HARF</span>${game.mode==='duel'?`<span class="tag">${game.round}. TUR</span>`:''}</span><button class="icon-btn" data-action="rules" aria-label="Oyun kuralları">?</button></div>${game.mode==='duel'?playerHTML():''}
  <div class="game-grid"><section class="playboard" aria-label="Kelime oyun alanı"><div class="board-top"><span>${game.mode==='duel'?`<span id="turn-text">${esc(game.names[game.turn])}</span>`:'KELİME ZİNCİRİN'}</span><span class="score-inline"><strong id="move-count">${game.moves}</strong> kelime</span>${game.mode==='calm'?'<span aria-label="Süresiz" class="timer">∞</span>':'<span class="timer" id="timer" role="timer" aria-live="off"></span>'}</div>${game.mode!=='calm'?'<div class="clock-track"><div class="clock-fill" id="clock-fill"></div></div>':''}
  <div class="current-label" id="current-label">${esc(game.current)} kelimesinden devam et</div><div class="word-tiles ${game.length===5?'long':''}" id="word-tiles" role="group" aria-label="Değiştirmek istediğin harfi seç"></div><p class="board-instruction">Bir kutuya dokun, yeni harfi seç.</p><p class="feedback ${feedbackType}" id="feedback" role="status" aria-live="polite">${esc(feedback)}</p>
  <div class="keyboard" aria-label="Türkçe harf klavyesi">${['QWERTYUIOPĞÜ','ASDFGHJKLŞİ','ZXCVBNMÖÇ'].map(row=>`<div class="key-row">${[...row].filter(c=>!'QWX'.includes(c)).map(c=>`<button class="key" data-action="key" data-key="${c}" aria-label="${c} harfi">${c}</button>`).join('')}</div>`).join('')}</div>
  <div class="board-actions"><button class="small-icon" data-action="reset" aria-label="Değişikliği geri al" title="Geri al">↶</button><button class="primary lime" data-action="submit">Kelimeyi gönder <span>↵</span></button><button class="small-icon" data-action="${game.mode==='duel'?'rules':'hint'}" aria-label="${game.mode==='duel'?'Kurallar':'İpucu göster'}" title="${game.mode==='duel'?'Kurallar':'İpucu'}">${game.mode==='duel'?'?':'✧'}</button></div>
  <div class="type-toggle"><button data-action="typing">${typed?'Harf kutularına dön':'Kelimeyi yazarak gir'}</button></div>${typed?`<form class="typed-form" id="typed-form"><label class="sr-only" for="typed-word" style="position:absolute;clip-path:inset(50%);height:1px;width:1px;overflow:hidden">Yeni kelime</label><input id="typed-word" class="typed-input" maxlength="${game.length+3}" value="${esc(draft)}" autocomplete="off" autocorrect="off" autocapitalize="characters" spellcheck="false" aria-label="Yeni kelime"><button type="submit">Gönder</button></form>`:''}
  ${game.status==='paused'?'<div class="paused-overlay"><span class="pause-symbol">Ⅱ</span><h2>Küçük bir mola.</h2><p>Hazır olduğunda kelimeler burada.</p><button class="primary" data-action="resume">Devam et ↗</button></div>':''}</section>
  <aside class="side-panel"><div class="journey"><div class="journey-head"><span>İz bıraktığın kelimeler</span><span id="history-count">${game.history.length}</span></div><ol class="history" id="history">${historyHTML()}</ol></div><div class="tip-card"><div class="tip-label">${game.mode==='duel'?'BİR HAMLE SONRASI':'KÜÇÜK BİR İPUCU'}</div><p>${game.mode==='duel'?'Sadece kelime bulma. Rakibine bıraktığın kelimenin çıkışlarını da düşün.':'İlk harfe takılma. Ortadaki veya sondaki harfi değiştirmek bambaşka bir yol açabilir.'}</p><button class="text-btn" data-action="rules">Kuralları hatırla ↗</button></div><div class="tip-card"><div class="tip-label">${game.mode==='duel'?'DÜELLO KURALI':'KENDİNLE YARIŞ'}</div><p>${game.mode==='duel'?'Kullanılan kelimeler ikiniz için de yasak. İlk 3 turu kazanan maçın sahibi.':`Bu modda, ${game.length} harfle yardımsız rekorun: <strong>${stats.best[recordKey()]||0}</strong> kelime.`}</p></div></aside></div>
  <div class="game-bottom">${game.mode==='duel'?'<button class="secondary" data-action="concede">Bu turu bırak</button>':'<div style="display:flex;gap:8px"><button class="secondary" data-action="pause">Ⅱ Mola</button><button class="secondary" data-action="finish">Tamamla</button></div>'}<span class="small-note" id="assisted-note">${game.mode==='duel'?'Süre dolmadan hamleni yap.':game.assisted?'✧ İpucu kullanılan oyun':'Her kelime yeni bir adım.'}</span></div>`;
  renderTiles();updateClock();scrollHistory();
}
function renderTiles(){const el=$('#word-tiles');if(!el||!game)return;el.innerHTML=[...draft].map((c,i)=>`<button class="letter ${selected===i?'selected':''} ${c!==game.current[i]?'changed':''}" data-action="tile" data-index="${i}" aria-label="${i+1}. harf ${esc(c)}, değiştirmek için seç" aria-pressed="${selected===i}">${esc(c)}<span class="letter-index" aria-hidden="true">${i+1}</span></button>`).join('');}
function updateFeedback(message,type=''){feedback=message;feedbackType=type;const el=$('#feedback');if(el){el.textContent=message;el.className='feedback '+type;}}
function updateClock(){if(!game||!$('#timer'))return;const s=Math.ceil(remaining(game)/1000);$('#timer').textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;$('#timer').classList.toggle('urgent',s<=10);$('#clock-fill').style.width=`${Math.min(100,remaining(game)/DURATIONS[game.mode]*100)}%`;$('#clock-fill').classList.toggle('urgent',s<=10);}
function scrollHistory(){const el=$('#history');if(el)el.scrollTop=el.scrollHeight;}
function selectTile(index){if(game?.status!=='playing')return;selected=index;renderTiles();}
function enterLetter(key){if(game?.status!=='playing')return;const letter=normalize(key);if(!/^[A-ZÇĞİÖŞÜ]$/.test(letter)||'QWX'.includes(letter))return;draft=game.current.slice(0,selected)+letter+game.current.slice(selected+1);renderTiles();const inp=$('#typed-word');if(inp)inp.value=draft;updateFeedback(letter===game.current[selected]?'Yeni bir harf seç.':'Hazırsan kelimeyi gönder.');}
function sendWord(raw=draft){
  if(!game)return;const result=submit(game,raw);if(!result.ok){if(game.status==='ended'){showResult();return;}updateFeedback(result.message,'error');playSound('error');$('#word-tiles')?.classList.add('shake');setTimeout(()=>$('#word-tiles')?.classList.remove('shake'),280);return;}
  draft=game.current;playSound('success');persist();
  const praise=game.moves%10===0?`${game.moves} kelime! Harfler senden sorulur.`:game.moves%5===0?'Güzel gidiyorsun. Bir yol daha açıldı.':`${result.word} ✓ Yeni bir yol açıldı.`;
  feedback=result.newChain?'Çıkış kalmadı; yeni zincir açıldı. Süre devam ediyor!':game.mode==='duel'?`${result.word} ✓ Sıra ${game.names[game.turn]} oyuncusunda.`:praise;feedbackType='success';
  if(game.status==='ended'){renderGame();showResult();return;}
  renderGame();$('#word-tiles')?.classList.add('pop');setTimeout(()=>$('#word-tiles')?.classList.remove('pop'),280);
}
function openModal(html,kind='info') {
  if(game?.status==='playing'&&game.mode!=='duel'&&kind!=='result'){modalPaused=pause(game);updateClock();}else modalPaused=false;
  modalKind=kind;$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();
}
function closeModal(autoResume=true){if(modal.open)modal.close();if(autoResume&&modalPaused&&game?.status==='paused'){resume(game);updateClock();}modalPaused=false;modalKind='';}
function rules(){openModal(`<p class="modal-eyebrow">KEK'E HOŞ GELDİN</p><h2 class="modal-title">Bir harf yeter.</h2><p class="modal-desc">KEK → ÇEK → ÇOK. Mantık bu kadar basit. Yolun ne kadar uzayacağı sana bağlı.</p><ol class="rules-list"><li><span><strong>Tek harf değişir.</strong> Harf ekleyemez, silemez veya yerini değiştiremezsin. Aynı harf konumunu sonraki hamlede yeniden seçebilirsin.</span></li><li><span><strong>Çekim eki yok.</strong> EVİ, EVE, EVDE gibi biçimler kabul edilmez. Yalnızca bağımsız sözlük maddeleri geçer. KAZMA, İŞSİZ, SÜTÇÜ gibi bağımsız kelimeler ve ALMAK gibi sözlükteki mastarlar geçerlidir. GEL ve GİT gibi emir biçimleri eklenmez.</span></li><li><span><strong>Tekrar yok.</strong> Başlangıç kelimesi dahil, bu turda kullanılan her kelime herkes için kapanır.</span></li><li><span><strong>Türkçe harfler ayrı.</strong> I–İ, O–Ö ve U–Ü farklıdır. Düzeltme işareti sadeleştirilir: KÂR → KAR. Özel isim ve kısaltma sözlükleri kullanılmaz.</span></li></ol><p class="modal-note"><strong>Sakin akış:</strong> Süre yok; otomatik kaydedilir.<br><strong>Zamana karşı:</strong> 120 saniye; çıkış kalmazsa yeni zincir açılır. Sekme arka plandayken süre işler. Mola düğmesi süreyi durdurur.<br><strong>Düello:</strong> Aynı cihazda iki kişi, hamle başına 30 saniye. Hamlesiz kalan veya süresi dolan turu kaybeder. Başlayan oyuncu her tur değişir; ilk 3 turu kazanan maçı alır.<br><strong>İpucu:</strong> Tek kişilik modlarda var; yardımlı rekorlar ayrı tutulur.</p>${game?.mode==='duel'?'<p class="modal-note">Düelloda süre bu pencere açıkken de işler.</p>':''}<div class="dialog-actions"><button class="primary" data-action="close">Anladım, devam ↗</button></div>`,'rules');}
function records(){const rows=['calm','rush'].flatMap(mode=>[3,4,5].map(n=>`<tr><td>${labels[mode]} · ${n} harf</td><td>${stats.best[`${mode}:${n}`]||'—'}</td><td>${stats.assisted[`${mode}:${n}`]||'—'}</td></tr>`)).join('');openModal(`<p class="modal-eyebrow">KENDİ YOLUN, KENDİ REKORUN</p><h2 class="modal-title">Her kelime bir adım.</h2><p class="modal-desc">${Number(stats.games)||0} tamamlanan tur · ${Number(stats.total)||0} bulunan kelime</p><table class="records-table"><thead><tr><th>Oyun</th><th>Yardımsız</th><th>İpucuyla</th></tr></thead><tbody>${rows}</tbody></table><p class="modal-note">Rekorlar bu tarayıcıda tutulur. Tarayıcı verileri silinirse kayıtlar da silinir. Farklı cihazlarla eşitlenmez.</p><div class="dialog-actions"><button class="primary" data-action="close">Yeni bir yol bul ↗</button></div>`,'records');}
function dictionaryModal(){
  if(game?.status==='playing'||game?.status==='paused'){toast('Kelime araması oyun dışında kullanılabilir.');return;}
  openModal(`<p class="modal-eyebrow">HARFLERİN BULUŞMA NOKTASI</p><h2 class="modal-title">Oyun sözlüğü.</h2><p class="modal-desc">${dictionary.size.toLocaleString('tr-TR')} bağımsız sözlük maddesi · 3, 4 ve 5 harf. Zemberek kaynakları ve ek kelime seçkisi. Türkçedeki her kelimeyi kapsama iddiası yok.</p><label class="setup-label" for="word-search">Bir kelime veya başlangıcını ara</label><input id="word-search" class="search-input" placeholder="Örneğin: KEK" maxlength="30" autocomplete="off" spellcheck="false"><div id="search-summary" class="search-summary">Aramak için yazmaya başla.</div><div id="word-grid" class="word-grid"></div><p class="modal-note">Çekim eki yok: EVİ ve EVE geçmez. Bağımsız maddeler geçer: KAZMA, İŞSİZ, SÜTÇÜ, ALMAK. Zemberek NLP (Apache 2.0) + KEK ek seçkisi · sözlük ${DICTIONARY_VERSION}.</p>`,'dictionary');
}
function searchWords(query){const q=normalize(query),found=q?[...dictionary].filter(w=>w.startsWith(q)):[];const exact=dictionary.has(q);$('#search-summary').textContent=q?(exact?`${q} kabul edilir. `:'Tam eşleşme yok. ')+`${found.length} kelime bu harflerle başlıyor.${found.length>80?' İlk 80 gösteriliyor.':''}`:'Aramak için yazmaya başla.';$('#word-grid').innerHTML=found.slice(0,80).map(w=>`<span class="word-chip">${w}</span>`).join('');}
function record(){if(game.recorded)return;game.recorded=true;stats.games=(Number(stats.games)||0)+1;stats.total=(Number(stats.total)||0)+game.moves;if(game.mode==='duel'){stats.duels=(Number(stats.duels)||0)+1;}else{const bucket=game.assisted?stats.assisted:stats.best;game.newRecord=game.moves>(bucket[recordKey()]||0);bucket[recordKey()]=Math.max(bucket[recordKey()]||0,game.moves);}storage.set('stats',stats);persist();}
function celebration(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<25;i++){const bit=document.createElement('span');bit.className='confetti';bit.style.left=`${Math.random()*100}%`;bit.style.background=['#d5ed72','#edb598','#aacbe5'][i%3];bit.style.animationDelay=`${Math.random()*.45}s`;document.body.append(bit);setTimeout(()=>bit.remove(),2600);}}
function showResult(){
  if(!game||game.status!=='ended')return;record();const duel=game.mode==='duel',matchOver=duel&&game.scores.some(s=>s>=3);const candidates=available(game.current,game.used).slice(0,5);let title=duel?`${game.names[game.winner]}, ${matchOver?'maç senin!':'tur senin!'}`:game.reason==='blocked'?'Bu yol tamamlandı.':game.reason==='timeout'?'İki dakika, bir sürü kelime.':'Güzel bir yolculuktu.';
  const reason=duel?(game.reason==='blocked'?'Rakibe geçerli hamle kalmadı.':game.reason==='timeout'?`${game.names[1-game.winner]} süre içinde hamle yapamadı.`:'Rakibin bu turu bıraktı.'):game.reason==='blocked'?'Bu kelimeden kullanılmamış bir çıkış kalmadı.':'Bir sonraki zincirde başka yollar keşfedebilirsin.';
  openModal(`<div class="result-summary"><span class="result-symbol">${duel?'♜':game.newRecord?'✳':'↗'}</span><p class="modal-eyebrow">${duel?matchOver?'MAÇ TAMAMLANDI':`${game.round}. TUR TAMAMLANDI`:'KELİMELER İZ BIRAKIR'}</p><h2 class="modal-title">${esc(title)}</h2>${duel?`<div class="result-score" style="font-size:52px;letter-spacing:2px">${game.scores[0]} : ${game.scores[1]}</div><p class="result-caption">${esc(game.names[0])} · ${esc(game.names[1])}</p>`:`<div class="result-score">${game.moves}</div><p class="result-caption">yeni kelime buldun</p>`}${game.newRecord?`<div class="record-banner">✦ Yeni ${game.assisted?'yardımlı':'kişisel'} rekor!</div>`:''}<div class="result-stats"><div><strong>${game.length}</strong><span>HARF</span></div><div><strong>${duel?game.moves:game.chains}</strong><span>${duel?'HAMLE':'ZİNCİR'}</span></div><div><strong>${duel?game.round:game.hints}</strong><span>${duel?'TUR':'İPUCU'}</span></div></div></div><p class="modal-desc">${esc(reason)}</p>${!duel&&candidates.length?`<div class="tip-label" style="font-size:11px">${esc(game.current)} kelimesinden şu yollar da açıktı:</div><div class="word-suggestions">${candidates.map(w=>`<span class="word-chip">${w}</span>`).join('')}</div>`:''}${game.assisted?'<p class="small-note">İpucu kullanıldı; bu sonuç yardımlı rekorlara işlendi.</p>':''}<div class="dialog-actions"><button class="primary" data-action="${duel&&!matchOver?'next-round':'again'}">${duel&&!matchOver?'Sonraki tur':duel?'Rövanş':'Bir daha oyna'} ↗</button><button class="secondary" data-action="result-home">Ana sayfa</button></div><div style="text-align:center;margin-top:20px"><button class="text-btn" data-action="copy">Sonucumu kopyala</button></div>`,'result');
  if(game.newRecord||duel){playSound('win');celebration();}
}
function confirmExit(){if(!game||game.status==='ended'){showHome();return;}openModal(`<p class="modal-eyebrow">KISA BİR ARA MI?</p><h2 class="modal-title">Ana sayfaya dönelim mi?</h2><p class="confirm-text">${game.mode==='calm'?'Zincirin kaydedildi. Ana sayfadaki “Devam et” ile kaldığın yerden oynayabilirsin.':game.mode==='duel'?'Devam eden maç ve skorlar sonlandırılacak. Bu yarım tur rekorlara işlenmez.':'Bu süreli deneme sonlandırılacak ve rekorlara işlenmeyecek.'}</p><div class="dialog-actions"><button class="secondary" data-action="close">Oyunda kal</button><button class="primary" data-action="exit-confirm">Ana sayfaya dön</button></div>`,'exit');persist();}
function confirmFinish(){openModal(`<p class="modal-eyebrow">${game.mode==='duel'?'RAKİBE BİR TUR':'ZİNCİRİN HAZIR'}</p><h2 class="modal-title">${game.mode==='duel'?'Bu turu bırakıyor musun?':'Zinciri tamamlayalım mı?'}</h2><p class="confirm-text">${game.mode==='duel'?`${esc(game.names[1-game.turn])} bu turu kazanacak. Maç ilk 3 turu kazanana kadar devam eder.`:`Bulduğun ${game.moves} kelime sonuçlarına kaydedilecek.`}</p><div class="dialog-actions"><button class="secondary" data-action="close">Devam et</button><button class="primary" data-action="finish-confirm">${game.mode==='duel'?'Turu bırak':'Tamamla'}</button></div>`,'finish');}
function requestHint(){if(!game||game.mode==='duel')return;const word=hint(game);if(!word)return;const index=[...word].findIndex((c,i)=>c!==game.current[i]);updateFeedback(`İpucu: ${index+1}. harfi ${word[index]} yap → ${word}. Göndermek sana kalmış.`);const note=$('#assisted-note');if(note)note.textContent='✧ İpucu kullanılan oyun';persist();}
document.addEventListener('click',event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
  if(action==='sound'){sound=!sound;storage.set('sound',sound);soundButton();if(sound)playSound();return;}
  if(action==='rules'){rules();return;}if(action==='records'){records();return;}if(action==='dictionary'){dictionaryModal();return;}
  if(action==='close'){if(modalKind==='result'){closeModal();showHome();}else closeModal();return;}
  if(action==='home'||action==='exit'){if(game)confirmExit();else showHome();return;}
  if(action==='mode'){options.mode=el.dataset.mode;renderHome();return;}
  if(action==='length'){options.length=Number(el.dataset.length);renderHome();return;}
  if(action==='start'){
    if(saved&&options.mode==='calm'){openModal('<p class="modal-eyebrow">YENİ BİR BAŞLANGIÇ</p><h2 class="modal-title">Yeni zincir mi?</h2><p class="confirm-text">Kayıtlı sakin oyununun yerine yeni bir zincir başlayacak.</p><div class="dialog-actions"><button class="secondary" data-action="continue">Kayıtlı oyuna dön</button><button class="primary" data-action="start-fresh">Yeni oyun</button></div>','new');}else begin();return;}
  if(action==='start-fresh'){storage.remove('session');saved=null;begin();return;}
  if(action==='continue'){game=saved;options={mode:'calm',length:game.length};draft=game.current;selected=0;typed=false;feedback='Kaldığın yerden devam. Yol hâlâ açık.';feedbackType='';closeModal(false);renderGame();window.scrollTo({top:0,behavior:'instant'});return;}
  if(action==='result-home'||action==='exit-confirm'){persist();closeModal(false);showHome();return;}
  if(action==='again'){options={mode:game.mode,length:game.length};begin();return;}
  if(action==='next-round'){begin(true);return;}
  if(action==='tile'){selectTile(Number(el.dataset.index));return;}
  if(action==='key'){enterLetter(el.dataset.key);return;}
  if(action==='submit'){sendWord();return;}
  if(action==='reset'&&game?.status==='playing'){draft=game.current;renderTiles();if($('#typed-word'))$('#typed-word').value=draft;updateFeedback('Değişiklik geri alındı.');return;}
  if(action==='typing'&&game?.status==='playing'){typed=!typed;renderGame();if(typed){$('#typed-word').focus();$('#typed-word').select();}return;}
  if(action==='hint'){requestHint();return;}
  if(action==='pause'){if(pause(game)){persist();renderGame();}else if(game.status==='ended')showResult();return;}
  if(action==='resume'){resume(game);renderGame();return;}
  if(action==='finish'||action==='concede'){if(game.status==='playing')confirmFinish();return;}
  if(action==='finish-confirm'){closeModal(false);finish(game,game.mode==='duel'?'concede':'completed',Date.now(),game.mode==='duel'?1-game.turn:null);renderGame();showResult();return;}
  if(action==='copy'){const text=game.mode==='duel'?`KEK düellosu: ${game.names[0]} ${game.scores[0]}–${game.scores[1]} ${game.names[1]} · ${game.length} harf`:`KEK · ${labels[game.mode]} · ${game.length} harf · ${game.moves} kelime${game.assisted?' · ipucuyla':''}\n${game.history.map(i=>i.word).join(' → ')}`;navigator.clipboard?.writeText(text).then(()=>toast('Sonuç kopyalandı.')).catch(()=>toast('Tarayıcı kopyalamaya izin vermedi.'));return;}
});
document.addEventListener('input',event=>{if(event.target.matches('[data-player]')){names[Number(event.target.dataset.player)]=event.target.value;storage.set('names',names);}if(event.target.id==='word-search')searchWords(event.target.value);});
document.addEventListener('submit',event=>{if(event.target.id==='typed-form'){event.preventDefault();sendWord($('#typed-word').value);}});
document.addEventListener('keydown',event=>{
  if(modal.open||!game||game.status!=='playing'||event.ctrlKey||event.metaKey||event.altKey||['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName))return;
  if(event.key==='Enter'){if(event.target.closest('button')&&!event.target.closest('.key,.letter'))return;event.preventDefault();sendWord();}
  else if(event.key==='ArrowRight'){event.preventDefault();selected=(selected+1)%game.length;renderTiles();}
  else if(event.key==='ArrowLeft'){event.preventDefault();selected=(selected+game.length-1)%game.length;renderTiles();}
  else if(event.key==='Backspace'||event.key==='Delete'){event.preventDefault();draft=game.current;renderTiles();updateFeedback('Değişiklik geri alındı.');}
  else if(event.key.length===1&&/^[a-zA-ZçÇğĞıİöÖşŞüÜâÂîÎûÛ]$/.test(event.key)){event.preventDefault();enterLetter(event.key);}
});
modal.addEventListener('cancel',event=>{event.preventDefault();if(modalKind==='result'){closeModal();showHome();}else closeModal();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)persist();else if(game){tick(game);if(game.status==='ended'&&!game.recorded)showResult();updateClock();}});
setInterval(()=>{if(!game||game.status!=='playing')return;tick(game);updateClock();if(game.status==='ended')showResult();},200);
window.addEventListener('pagehide',persist);
soundButton();renderHome();
